function projects(){const visibleTasks=taskRecords.slice(projectOffset,projectOffset+10).filter(t=>t.join(' ').toLowerCase().includes(projectSearch.toLowerCase()));const month=new Date(2025,4+projectMonthOffset,1),monthName=month.toLocaleDateString('en-US',{month:'long',year:'numeric'}),start=month.getDay(),days=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();return `<div class="projects-layout"><main class="projects-main"><header class="projects-header"><div><div class="projects-eyebrow">Execution <span>›</span> Projects &amp; Tasks</div><h1>Projects &amp; Tasks</h1><p>Track your projects, manage tasks, and turn your ideas into results.</p></div><div class="projects-controls"><div class="project-view-switch">${['List','Board','Calendar'].map(v=>`<button data-project-view="${v}" class="${projectView===v?'active':''}">${v==='List'?'☷':v==='Board'?'☷':'▦'} <span>${v}</span></button>`).join('')}</div><select aria-label="Project filter"><option>All Projects</option>${projectRecords.map(p=>`<option>${p[0]}</option>`).join('')}</select></div></header><div class="project-metrics"><div><span>Total Projects</span><strong>8</strong><em>↑ 1 new</em></div><div><span>Active Projects</span><strong>5 <small>◌ 62%</small></strong></div><div><span>Completed</span><strong>2 <small class="green">◉ 25%</small></strong></div><div><span>Overdue Tasks</span><strong>3 <small class="red">↓ 2</small></strong></div></div><section class="projects-section"><div class="projects-section-head"><h2>My Projects</h2><button data-project-action="all-projects">View All →</button></div><div class="project-strip">${projectRecords.map((p,i)=>`<article class="project-item" style="--project-color:${p[5]}"><div class="project-item-top"><i>${p[6]}</i><div><b>${p[0]}</b><small>${p[1]}</small></div><button aria-label="Project options" data-project-action="options">⋮</button></div><div class="project-progress"><span><i style="width:${p[2]}%"></i></span><b>${p[2]}%</b></div><small class="project-task-count">♧ ${p[3]} tasks · <em>${p[4]} overdue</em></small></article>`).join('')}</div></section><section class="projects-task-section"><div class="projects-task-head"><div class="project-task-tabs">${[['My Tasks',18],['Assigned to Me',6],['Created by Me',12]].map(([t,n])=>`<button data-task-tab="${t}" class="${projectTaskTab===t?'active':''}">${t}<b>${n}</b></button>`).join('')}</div><div class="project-task-actions"><select><option>All Priorities</option><option>High</option><option>Medium</option><option>Low</option></select><select><option>All Statuses</option><option>To Do</option><option>In Progress</option><option>Blocked</option></select><button class="button primary" data-project-action="add-task">＋ Add Task</button></div></div><div class="project-table-wrap"><table class="project-table"><thead><tr><th><input type="checkbox" aria-label="Select all tasks"></th><th>Task</th><th>Project</th><th>Priority</th><th>Status</th><th>Due Date</th><th>Assignee</th><th></th></tr></thead><tbody>${visibleTasks.map((t,i)=>`<tr><td><input type="checkbox" class="project-check" aria-label="Complete ${t[0]}"></td><td><span class="project-task-name"><i>${['▣','▣','◈','▧'][i%4]}</i><span><b>${t[0]}</b><small>${t[1]}</small></span></span></td><td>${t[2]}</td><td><span class="task-priority ${t[3].toLowerCase()}">${t[3]}</span></td><td><span class="task-status ${t[4].toLowerCase().replaceAll(' ','-')}">${t[4]}</span></td><td>${t[5]}</td><td><span class="task-assignee"><i>ST</i>You</span></td><td><button class="task-more" aria-label="More task options">···</button></td></tr>`).join('')||'<tr><td colspan="8" class="project-empty">No tasks match this search.</td></tr>'}</tbody></table></div><div class="project-table-footer"><span>Showing ${Math.min(projectOffset+1,taskRecords.length)} – ${Math.min(projectOffset+10,taskRecords.length)} of 18 tasks</span><div>${[0,1].map(i=>`<button data-project-page="${i}" class="${Math.floor(projectOffset/10)===i?'active':''}">${i+1}</button>`).join('')}<button data-project-page="next">›</button></div></div></section><div class="projects-note">Project and task data is illustrative · sample workspace</div></main><aside class="projects-rail"><section class="project-side-section"><div class="project-side-head"><h2>${monthName}</h2><div><button data-month-shift="-1">‹</button><button data-month-shift="1">›</button></div></div><div class="mini-calendar"><div class="calendar-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-days">${Array.from({length:start},()=>'<i></i>').join('')}${Array.from({length:days},(_,i)=>`<button class="${i+1===19&&!projectMonthOffset?'today':''} ${[19,20,21,22,24,25].includes(i+1)?'has-task':''}">${i+1}</button>`).join('')}</div></div></section><section class="project-side-section"><div class="project-side-head"><h2>Upcoming Deadlines</h2><button data-project-action="deadlines">View All →</button></div>${[['red','Fix deployment issue (Vercel)','Photography Booking Site','Today, May 19'],['amber','Design dashboard UI','Personal Dashboard','May 22'],['blue','Add payment integration','Photography Booking Site','May 21'],['teal','Complete student management module','Hogwarts School App','May 24'],['purple','Investor deck for SaaS concept','Business Platform','May 25']].map(d=>`<div class="deadline-row"><i class="${d[0]}"></i><div><b>${d[1]}</b><small>${d[2]}</small></div><time>${d[3]}</time></div>`).join('')}</section><section class="project-side-section"><div class="project-side-head"><h2>Task Progress</h2></div><div class="task-progress-content"><div class="task-donut"><div><b>18</b><small>Total Tasks</small></div></div><div class="task-legend">${[['#00d7b4','Completed','8','44%'],['#168bff','In Progress','5','28%'],['#466386','To Do','4','22%'],['#ff536b','Overdue','3','17%']].map(l=>`<p><i style="background:${l[0]}"></i><span>${l[1]}</span><b>${l[2]}</b><small>${l[3]}</small></p>`).join('')}</div></div></section><section class="project-side-section"><div class="project-side-head"><h2>Recent Activity</h2><button data-project-action="activity">View All →</button></div>${[['#00d7b4','✓','You updated task “Fix deployment issue”','2 hours ago'],['#168bff','◉','You completed “Design dashboard UI”','5 hours ago'],['#a64cff','＋','You created new project “SaaS Platform”','1 day ago']].map(a=>`<div class="project-activity"><i style="--activity:${a[0]}">${a[1]}</i><span><b>${a[2]}</b><small>${a[3]}</small></span></div>`).join('')}</section></aside></div>`}
function wireProjects(){document.querySelectorAll('[data-project-view]').forEach(b=>b.addEventListener('click',()=>{projectView=b.dataset.projectView;if(projectView!=='List')toast(`${projectView} view selected.`);render('projects')}));document.querySelectorAll('[data-task-tab]').forEach(b=>b.addEventListener('click',()=>{projectTaskTab=b.dataset.taskTab;render('projects')}));document.querySelectorAll('[data-project-page]').forEach(b=>b.addEventListener('click',()=>{projectOffset=b.dataset.projectPage==='next'?Math.min(projectOffset+10,10):Number(b.dataset.projectPage)*10;render('projects')}));document.querySelectorAll('[data-month-shift]').forEach(b=>b.addEventListener('click',()=>{projectMonthOffset+=Number(b.dataset.monthShift);render('projects')}));document.querySelectorAll('[data-project-action]').forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.projectAction;if(a==='add-task'){openModal('#quickModal','#quickInput');$('#quickType').value='Task';$('#quickInput').placeholder='Describe the task…'}else if(a==='all-projects')toast('Showing all projects.');else if(a==='deadlines')toast('Showing all upcoming deadlines.');else if(a==='activity')toast('Showing recent project activity.');else toast('Project actions opened.')}));document.querySelectorAll('.project-check').forEach(b=>b.addEventListener('change',()=>{b.closest('tr').classList.toggle('completed',b.checked);toast(b.checked?'Task marked complete.':'Task reopened.')}))}
function generic(page){const specs={inbox:['Capture incoming ideas and turn them into clear next steps.',['Quick capture','Tasks to triage','Research notes']],finances:['Track assets, liabilities, income, expenses, and cash flow.',['Net worth history','Monthly cash flow','Financial goals']],investments:['Follow your holdings, transactions, performance, and income.',['Portfolio overview','Holdings & transactions','Dividends & income']],research:['Research companies with source-linked facts, assumptions, and notes.',['Company watchlist','Valuation workspace','Investment journal']],businesses:['Manage ventures, products, customers, revenue, and milestones.',['Business portfolio','Revenue & costs','Products & opportunities']],websites:['Monitor domains, applications, deployments, health, and infrastructure.',['Website registry','Domains & renewals','Uptime & deployments']],projects:['Connect projects, priorities, tasks, deadlines, and time.',['Active projects','Priority tasks','Time & opportunity cost']],development:['Keep repositories, releases, issues, and project documentation together.',['Repository directory','Issues & releases','Technical documentation']],learning:['Connect resources, skills, notes, and applied learning.',['Library & notes','Skills map','Applied learning']],assets:['Keep a reliable record of owned assets, liabilities, and important documents.',['Universal asset registry','Liabilities','Document vault']],personal:['Organize personal administration, well-being, and important commitments.',['Personal administration','Health & well-being','People & commitments']],analytics:['Understand change across your finances, ventures, technology, and execution.',['Wealth & cash flow','Business & product','Annual review']],automations:['Reduce repeat admin while keeping important decisions in your hands.',['Helpful automations','Ask your Personal AI','Integrations & intelligence feed']],settings:['Manage workspace preferences, data access, integrations, and security.',['Workspace preferences','Integrations & imports','Privacy & recovery']]};let [desc,cards]=specs[page]||specs.projects;return `<div class="page-header"><div class="page-title-wrap"><span class="page-icon">${page==='settings'?'⚙':'◈'}</span><div><h1 class="page-title">${navPages[page]||'LifeOS'}</h1><p class="page-subtitle">${desc}</p></div></div><button class="button primary" id="quickAdd">＋ Quick Add</button></div><div class="content-grid">${cards.map((c,i)=>`<article class="panel content-card"><span class="metric-symbol ${i===1?'blue':''}">${['◈','▣','⌁'][i%3]}</span><h3>${c}</h3><p>Connected records, history, reminders, and useful context for your ${c.toLowerCase()}.</p></article>`).join('')}</div><div class="panel content-panel" style="margin-top:10px"><div class="panel-head"><div><div class="panel-title">Your ${navPages[page]} will appear here</div><div class="panel-subtitle">Add your information, then connect it to the rest of your LifeOS.</div></div><button class="button primary" id="quickAdd">＋ Add a record</button></div><p class="sample-note" style="text-align:left;padding:8px 0">This workspace uses sample dashboard data. No bank, brokerage, repository, or website accounts are connected.</p></div>`}
