function inbox(){const filters=['All','Unread','Important','@ Mentions','System'],counts=[inboxMessages.length,inboxMessages.filter(m=>m.unread).length,inboxMessages.filter(m=>m.important).length,2,inboxMessages.filter(m=>m.system).length];let rows=inboxMessages.map((m,i)=>({m,i})).filter(({m})=>{const q=inboxSearch.toLowerCase(),match=!q||`${m.sender} ${m.subject} ${m.preview} ${m.category}`.toLowerCase().includes(q);return match&&(inboxFilter==='All'||inboxFilter==='Unread'&&m.unread||inboxFilter==='Important'&&m.important||inboxFilter==='@ Mentions'&&['GitHub','Notion'].includes(m.sender)||inboxFilter==='System'&&m.system)});if(!rows.some(x=>x.i===selectedInbox)&&rows.length)selectedInbox=rows[0].i;const selected=inboxMessages[selectedInbox];const items=rows.map(({m,i})=>`<button class="inbox-row ${i===selectedInbox?'selected':''} ${m.unread?'unread':''}" data-inbox-id="${i}"><span class="inbox-avatar ${m.tone}">${m.avatar}</span><span class="inbox-row-copy"><span class="inbox-row-top"><b>${m.sender}</b><time>${m.time}</time></span><strong>${m.subject}</strong><small>${m.preview}</small></span><span class="inbox-row-meta"><i class="inbox-category ${m.tone}">${m.category}</i><i class="inbox-unread-dot ${m.unread?'visible':''}"></i></span></button>`).join('');const toolbar=filters.map((f,i)=>`<button class="inbox-filter ${inboxFilter===f?'active':''}" data-inbox-filter="${f}">${f}<span>${counts[i]}</span></button>`).join('');const detail=selected.kind==='deploy'?`<div class="inbox-message-body"><div class="inbox-success"><span>✓</span><div><b>Your deployment was successful!</b><p>The production deployment for gar-frontend has been completed and is now live.</p></div></div><div class="deploy-details">${[['Project','gar-frontend'],['Environment','Production'],['Git Commit','◉ a1b2c3d4　↗　View commit'],['Branch','main'],['Deployed by','Vercel'],['Deployment URL','◉ https://gar-frontend.vercel.app　↗'],['Deployment time','May 19, 2025 at 10:42 AM (UTC)'],['Build duration','2m 14s']].map(r=>`<div><span>${r[0]}</span><b>${r[1]}</b></div>`).join('')}</div><a class="inbox-primary-link" href="#websites" data-goto="websites">◎ &nbsp;View Deployment <span>→</span></a><div class="deploy-preview"><div class="preview-window"><i></i><span>Find Your Perfect<br/>Property</span><b></b></div><div><strong>What’s next?</strong><p>✓ &nbsp;Monitor your application for any errors</p><p>✓ &nbsp;Check your analytics for traffic</p><p>✓ &nbsp;Set up alerts (optional)</p><a href="#projects" data-goto="projects">View your project on Vercel →</a></div></div><div class="related-activity"><b>Related Activity</b>${[['Build completed successfully','2m 14s'],['Deployment finished','1m 32s'],['Your site is live','10:42 AM']].map(r=>`<p><i>✓</i>${r[0]}<small>${r[1]}</small></p>`).join('')}</div></div>`:`<div class="inbox-message-body generic-message"><h3>${selected.sender} update</h3><p>${selected.preview.replace('…','')}</p><div class="deploy-details"><div><span>From</span><b>${selected.email}</b></div><div><span>Category</span><b>${selected.category}</b></div><div><span>Received</span><b>May 19, 2025 · ${selected.time}</b></div></div><p>Open the related section in LifeOS to see more context and keep your records up to date.</p><a class="inbox-primary-link" href="#${selected.category==='Finance'?'finances':selected.category==='Investments'?'investments':selected.category==='Calendar'?'calendar':'projects'}" data-goto="${selected.category==='Finance'?'finances':selected.category==='Investments'?'investments':selected.category==='Calendar'?'calendar':'projects'}">Open related section <span>→</span></a></div>`;return `<div class="inbox-layout"><header class="page-header inbox-page-header"><div class="page-title-wrap"><span class="page-icon">✉</span><div><h1 class="page-title">Inbox</h1><p class="page-subtitle">Your important updates, notifications and messages in one place.</p></div></div><button class="button primary inbox-mobile-compose" data-inbox-action="compose">＋ Compose</button></header><section class="inbox-list-pane"><div class="inbox-list-toolbar"><label class="inbox-search"><span>⌕</span><input id="inboxSearch" type="search" placeholder="Search inbox" value="${inboxSearch.replaceAll('"','&quot;')}"></label><button class="button inbox-icon-action" data-inbox-action="list" aria-label="Change list view">☷</button><button class="button inbox-sort" data-inbox-action="sort">Newest first⌄</button></div><nav class="inbox-filters">${toolbar}</nav><div class="inbox-message-list">${items||'<div class="inbox-empty">No messages match this filter.</div>'}</div><div class="inbox-list-footer">${rows.length} messages <span>·</span> Synced just now</div></section><section class="inbox-reader"><div class="inbox-reader-toolbar"><div class="inbox-nav-actions"><button class="button inbox-icon-action" data-inbox-action="previous" aria-label="Previous message">‹</button><button class="button inbox-icon-action" data-inbox-action="next" aria-label="Next message">›</button></div><div class="inbox-reader-actions"><button class="button inbox-icon-action" data-inbox-action="important" aria-label="Toggle important">${selected.important?'★':'☆'}</button><button class="button inbox-icon-action" data-inbox-action="archive" aria-label="Archive message">▤</button><button class="button inbox-mark-read" data-inbox-action="read">${selected.unread?'Mark as read':'Mark unread'}</button><button class="button inbox-icon-action" data-inbox-action="more" aria-label="More message options">···</button></div></div><article class="inbox-message"><div class="inbox-sender"><span class="inbox-avatar ${selected.tone}">${selected.avatar}</span><div><b>${selected.sender}</b><small>${selected.email}</small></div><time>May 19, 2025 · ${selected.time}</time></div><h2>${selected.subject}</h2><span class="inbox-category ${selected.tone}">${selected.category}</span>${detail}</article></section></div>`}
function wireInbox(){document.querySelectorAll('[data-inbox-filter]').forEach(b=>b.addEventListener('click',()=>{inboxFilter=b.dataset.inboxFilter;render('inbox')}));document.querySelectorAll('[data-inbox-id]').forEach(b=>b.addEventListener('click',()=>{selectedInbox=Number(b.dataset.inboxId);inboxMessages[selectedInbox].unread=false;render('inbox')}));$('#inboxSearch')?.addEventListener('input',e=>{inboxSearch=e.target.value;const pos=e.target.selectionStart;render('inbox');const input=$('#inboxSearch');input.focus();input.setSelectionRange(pos,pos)});document.querySelectorAll('[data-inbox-action]').forEach(b=>b.addEventListener('click',()=>{const action=b.dataset.inboxAction;if(action==='read'){inboxMessages[selectedInbox].unread=!inboxMessages[selectedInbox].unread;render('inbox')}else if(action==='important'){inboxMessages[selectedInbox].important=!inboxMessages[selectedInbox].important;render('inbox')}else if(action==='previous'||action==='next'){selectedInbox=(selectedInbox+(action==='next'?1:-1)+inboxMessages.length)%inboxMessages.length;inboxMessages[selectedInbox].unread=false;render('inbox')}else if(action==='compose')openModal('#quickModal','#quickInput');else toast(action==='archive'?'Message archived.':action==='sort'?'Inbox is sorted by newest first.':action==='list'?'Inbox list options.':'More message actions.')}))}
