const backgroundOptions = document.querySelectorAll('[data-background-choice]');
const applyBackgroundPreference = background => {
  const isBlack = background === 'black';
  document.body.classList.toggle('plain-black', isBlack);
  backgroundOptions.forEach(option => {
    const selected = option.dataset.backgroundChoice === background;
    option.classList.toggle('active', selected);
    option.setAttribute('aria-pressed', String(selected));
  });
};
let savedBackground = 'network';
try { savedBackground = localStorage.getItem('lifeos-background') || 'network'; } catch {}
applyBackgroundPreference(savedBackground);
backgroundOptions.forEach(option => option.addEventListener('click', () => {
  const background = option.dataset.backgroundChoice;
  try { localStorage.setItem('lifeos-background', background); } catch {}
  applyBackgroundPreference(background);
}));

